private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    if (!bb.hasRemaining()) {
        return i;
    }
    int units = 1; // number of code units appended
    int b0 = bb.get() & 0xFF;
    try {
        if (b0 <= 0x7F) { // one byte
            sb.append((char)b0);
        } else if ((b0 & 0xE0) == 0xC0) { // two bytes
            if (!bb.hasRemaining()) {
                return i;
            }
            int b1 = bb.get() & 0xFF;
            int ch = ((b0 & 0x1F) << 6) | (b1 & 0x3F);
            sb.append((char)ch);
        } else if ((b0 & 0xF0) == 0xE0) { // three bytes
            if (bb.remaining() < 2) {
                return i;
            }
            int b1 = bb.get() & 0xFF;
            int b2 = bb.get() & 0xFF;
            int ch = ((b0 & 0x0F) << 12) | ((b1 & 0x3F) << 6) | (b2 & 0x3F);
            sb.append((char)ch);
        } else if ((b0 & 0xF8) == 0xF0) { // four bytes
            if (bb.remaining() < 3) {
                return i;
            }
            int b1 = bb.get() & 0xFF;
            int b2 = bb.get() & 0xFF;
            int b3 = bb.get() & 0xFF;
            int codePoint = ((b0 & 0x07) << 18) | ((b1 & 0x3F) << 12) 
                            | ((b2 & 0x3F) << 6) | (b3 & 0x3F);
            sb.append(Character.toChars(codePoint));
            units = Character.charCount(codePoint); // typically 2 for surrogate pair
        } else { // invalid leading byte
            return i;
        }
    } catch (java.nio.BufferUnderflowException e) {
        return i;
    }
    return i + units;
