    long monthDay = timeBucket % 10000;
    long month = monthDay / 100;
    long day = monthDay % 100;
    if(month < 1 || month > 12){
        throw new IllegalArgumentException("Month value out of range: " + month);
    }
    if(day < 1 || day > 31){
        throw new IllegalArgumentException("Day value out of range: " + day);
    }
    long newDay = ((day - 1) / dayStep) * dayStep + 1;
    return year * 10000 + month * 100 + newDay;
}

